"""
    :type p: int
    :type q: int
    :rtype: list[int]
    """
def find_kaprecar_numbers(p: Any, q: Any) -> object {
    kaprecar_numbers = `list();
    for i in range(p, (q + 1)) {
        square = str((i ** 2));
        l_piece = square[:(len(square) // 2)] if (len(square) > 1) else "0";
        r_piece = square[len(l_piece):] if (len(square) > 1) else square;
        if ((int(l_piece) + int(r_piece)) == i) {
            kaprecar_numbers.append(i);
        }
    }
    return kaprecar_numbers;
}

test_blocks:
test "t0" {
    assert (find_kaprecar_numbers(2, 100) == [9, 45, 55, 99]);;
}

test "t1" {
    assert (find_kaprecar_numbers(1, 10) == [1, 9]);;
}

test "t2" {
    assert (find_kaprecar_numbers(1, 1000) == [1, 9, 45, 55, 99, 297, 703, 999]);;
}

